import {lessons,sources} from './content.js';
import {library,topics,exams,references,rubric} from './practice.js';
import {STORAGE_KEY,freshState,escapeHtml as e,grade,consolidated,validateState} from './core.js';
const $=(selector)=>document.querySelector(selector);
let state=freshState(),timer=null,recorder=null,stream=null,audioUrl=null,currentTab='learn',storageWarning=false;
try {const saved=localStorage.getItem(STORAGE_KEY);if(saved)state=validateState(JSON.parse(saved),lessons.map(l=>l.id));}catch{storageWarning=true;}
const levelSummary={B1:['Consolidar tu base','Cuenta experiencias y resuelve situaciones cotidianas.'],B2:['Ganar soltura','Explica, opina y responde con más libertad.'],C1:['Afinar tus matices','Interpreta, sintetiza y adapta tu forma de hablar.']};
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storageWarning=true;toast('Este navegador no permite guardar. Exporta una copia de tu progreso.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function link(url,label){return `<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`;}
const badge=(level)=>`<span class="badge level-${level}">${level}</span>`;
const eyebrow=text=>`<p class="eyebrow">${e(text)}</p>`;
const pageTitle=(small,title,desc)=>`${eyebrow(small)}<h1>${e(title)}</h1><p class="lead">${e(desc)}</p>`;
function progress(level){const list=lessons.filter(l=>l.level===level);return {list,done:list.filter(l=>consolidated(state,l.id)).length};}
function nextLesson(){return progress(state.level).list.find(l=>!consolidated(state,l.id))??progress(state.level).list[0];}
function lessonCard(l,index){const mastered=consolidated(state,l.id),score=state.results[l.id];return `<a class="lesson-card" href="#lesson/${l.id}"><span class="lesson-number">${String(index+1).padStart(2,'0')}</span><div>${badge(l.level)}<span class="tiny">${e(l.tag)}</span><h3>${e(l.title)}</h3><p>${e(l.goal)}</p></div><span class="lesson-meta">${mastered?'✓ Consolidada':score?`${score.percent}% · seguir practicando`:`${l.minutes} min`} <span aria-hidden="true">↗</span></span></a>`;}
function home(){
 const {done,list}=progress(state.level),next=nextLesson(),total=lessons.filter(l=>consolidated(state,l.id)).length;
 return `<section class="hero"><div>${eyebrow('TU ESPACIO PARA GANAR SOLTURA')}<h1>Más palabras.<br>Más <em>confianza.</em></h1><p>Del «sé lo que quiero decir» al «puedo explicarlo».<br>Un camino de español para hacerlo tuyo.</p><a class="button light" href="#lesson/${next.id}">${state.results[next.id]?'Continuar estudiando':'Empezar mi sesión'} <span>↗</span></a><span class="hero-note">${state.level} · ${e(next.title)}</span></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 330 310"><path d="M30 282 Q165 33 300 282" fill="#b9c69b"/><path d="M72 282 Q170 91 280 282" fill="#d6dfbd"/><path d="M109 282 Q205 174 280 282" fill="#edf0d7"/><circle cx="237" cy="54" r="31" fill="#f2c691"/><path d="M156 280 Q136 194 172 94 M156 231 Q104 224 89 181 Q146 176 156 231 M159 194 Q214 195 238 147 Q182 140 159 194 M164 145 Q126 123 132 83 Q173 94 164 145" fill="none" stroke="#43684e" stroke-width="5"/><path d="M34 282H302" stroke="#678461" stroke-width="2"/></svg><span>Un paso cada día.</span></div></section>
 <section class="stats" aria-label="Tu progreso"><div><span>${done}<small> / ${list.length}</small></span><p>unidades consolidadas en ${state.level}</p></div><div><span>${lessons.length}</span><p>unidades de B1 a C1</p></div><div><span>${lessons.reduce((n,l)=>n+l.quiz.length,0)+library.reduce((n,l)=>n+l.questions.length,0)}</span><p>preguntas con explicación</p></div><div><span>${total}</span><p>unidades consolidadas en total</p></div></section>
 <section class="section-heading"><div>${eyebrow('UN CAMINO QUE SE ADAPTA A TI')}<h2>Tu ritmo. Tu siguiente paso.</h2></div><a href="#route">Ver toda la ruta ↗</a></section>
 <div class="level-grid">${Object.entries(levelSummary).map(([level,[title,desc]])=>{const p=progress(level);return `<button class="level-card ${state.level===level?'selected':''}" data-level="${level}">${badge(level)}<span class="level-status">${state.level===level?'TU RUTA ACTUAL':'RUTA ABIERTA'}</span><h3>${title}</h3><p>${desc}</p><div class="progress-track"><span style="width:${p.done/p.list.length*100}%"></span></div><small>${p.done} de ${p.list.length} unidades consolidadas</small></button>`;}).join('')}</div>
 <section class="section-heading"><div>${eyebrow('PARA TU PRÓXIMA SESIÓN')}<h2>Aprender. Usarlo. Hacerlo tuyo.</h2></div></section>${lessonCard(next,list.indexOf(next))}
 <div class="two-col"><a class="feature-card" href="#conversation"><span class="feature-icon">◌</span><h3>Diez minutos de conversación</h3><p>Un tema, preguntas de apoyo y una segunda oportunidad para decirlo mejor.</p><span>Entrar al estudio oral ↗</span></a><a class="feature-card warm" href="#exams"><span class="feature-icon">✓</span><h3>Comprueba con un modelo real</h3><p>Cuadernillos oficiales del DELE y un registro para revisar cada habilidad.</p><span>Abrir controles ↗</span></a></div>
 ${storageWarning?'<p class="notice">El guardado local no está disponible o no se pudo leer. Usa la exportación del cuaderno para conservar tu trabajo.</p>':''}`;
}
function route(){const {list,done}=progress(state.level);return `${pageTitle('RUTA DE APRENDIZAJE',`${state.level} · ${levelSummary[state.level][0]}`,levelSummary[state.level][1])}<div class="route-tools"><p>${done} de ${list.length} consolidadas. Todas las unidades están abiertas.</p><label class="search-label">Buscar en todas las rutas <input type="search" id="search" placeholder="Subjuntivo, pasado, vocabulario…"></label></div><div id="lesson-list">${list.map(lessonCard).join('')}</div><section class="reference-section"><h2>Consulta rápida</h2><p>Un mapa para volver a una forma o una regla cuando la necesites.</p>${references.map(([title,text])=>`<details><summary>${e(title)}</summary><p>${e(text)}</p></details>`).join('')}</section><a class="button secondary" href="#method">Diseñar mi semana de estudio</a>`;}
function quizMarkup(id,items){return `<form class="quiz" data-quiz="${id}"><p class="quiz-intro">Responde sin mirar la explicación. Hay una opción prevista por pregunta. La corrección explicará el contexto.</p>${items.map((item,i)=>`<fieldset><legend><span>${i+1}</span> ${e(item.prompt)}</legend>${item.options.map((option,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}" required><span>${e(option)}</span></label>`).join('')}<div class="feedback" data-feedback="${i}" hidden></div></fieldset>`).join('')}<button class="button" type="submit">Corregir y entender</button><button class="button secondary" type="reset">Volver a intentarlo</button><div class="quiz-result" role="status" aria-live="polite"></div></form>`;}
function ratingMarkup(id){const values=state.ratings[id]??[];return `<form class="rating-form" data-ratings="${id}"><h3>Observa tu producción oral</h3><p>Escala de estudio propia: 1 = necesito mucho apoyo; 2 = tengo bloqueos frecuentes; 3 = me desenvuelvo con algunas dificultades; 4 = lo hago con soltura; 5 = lo hago con flexibilidad y precisión. No equivale a una nota DELE.</p>${rubric.map(([name,desc],i)=>`<label class="rating-row"><span><strong>${name}</strong><small>${desc}</small></span><select name="r${i}" required aria-label="Puntuación de ${name}"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${values[i]===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<button class="button secondary" type="submit">Guardar valoración</button></form>`;}
function speakingTools(){return `<div class="speech-tools"><div class="timer"><span id="timer-display" aria-live="off">02:00</span><label>Minutos <select id="timer-minutes"><option value="1">1</option><option value="2" selected>2</option><option value="3">3</option><option value="5">5</option><option value="10">10</option></select></label><button class="button secondary" id="timer-start">Iniciar</button><button class="text-button" id="timer-reset">Reiniciar</button></div><div class="recording"><button class="button secondary" id="record-start">Grabar mi voz</button><button class="button secondary" id="record-stop" disabled>Terminar grabación</button><div id="record-output" role="status"></div><p class="tiny">La grabación se crea en este dispositivo y no se sube. Descárgala antes de cambiar de sección. También puedes grabar con el móvil.</p></div></div>`;}
function lessonView(id){const l=lessons.find(l=>l.id===id);if(!l)return pageTitle('NO ENCONTRADO','Esa unidad no existe','Vuelve a la ruta para elegir una unidad.')+'<a href="#route">Ver la ruta</a>';
 state.lastLesson=id;save();const siblings=progress(l.level).list,index=siblings.indexOf(l),score=state.results[id];
 let body='';
 if(currentTab==='learn')body=`<div class="lesson-layout"><article class="reading-column">${state.english?`<p class="english-help"><strong>English help</strong> ${e(l.help)}</p>`:''}${l.sections.map(block=>`<section class="explanation"><h2>${e(block.title)}</h2><p>${e(block.text)}</p><ul class="examples">${block.examples.map(text=>`<li>${e(text)}</li>`).join('')}</ul></section>`).join('')}</article><aside class="lesson-aside"><h3>Frases para llevar contigo</h3>${l.chunks.map(chunk=>`<p class="chunk">${e(chunk)}</p>`).join('')}<p>Di cada frase con una situación de tu vida. Después úsala sin mirar.</p><h3>Una sesión de ${l.minutes} minutos</h3><ol><li>Entiende y contrasta ejemplos.</li><li>Responde sin mirar.</li><li>Habla y reformula.</li><li>Escribe y revisa.</li></ol></aside></div>`;
 if(currentTab==='quiz')body=`<h2>Comprueba lo que has entendido</h2>${score?`<p>Último intento: ${score.correct}/${score.total} · ${score.percent}%. Intentos guardados: ${score.attempts}. Repetir ayuda a aprender; para comprobar transferencia utiliza un modelo nuevo.</p>`:''}${quizMarkup(id,l.quiz)}`;
 if(currentTab==='speak')body=`<h2>De la explicación a la conversación</h2><p class="task-prompt">${e(l.speak)}</p><div class="three-col"><div><h3>Con apoyo</h3><p>Prepara cinco palabras y habla 60–90 segundos. Puedes consultar las frases útiles.</p></div><div><h3>Sin guion</h3><p>Habla dos minutos. Tu compañero hace dos preguntas que no conoces de antemano.</p></div><div><h3>Un paso más</h3><p>Añade una objeción, una condición o una comparación. Negocia una respuesta con tu compañero.</p></div></div><p>Después elige dos mejoras y vuelve a intentarlo. Para comprobar que las puedes transferir, utiliza otro tema al día siguiente.</p>${speakingTools()}${ratingMarkup(id)}`;
 if(currentTab==='write')body=`<h2>Escribe para ordenar tus ideas</h2><p class="task-prompt">${e(l.write)}</p><label class="editor-label" for="draft">Tu texto <span id="word-count"></span></label><textarea id="draft" data-draft="${id}" rows="13" placeholder="Escribe aquí. El borrador se guarda al escribir.">${e(state.drafts[id]??'')}</textarea><details><summary>Ver una respuesta de ejemplo después de escribir</summary><p>${e(l.model)}</p><p class="tiny">Este ejemplo ilustra recursos de la unidad. No sustituye una respuesta completa a todas las condiciones de la tarea.</p></details><h3>Revisión en tres pasadas</h3><ol><li>¿Respondo a la tarea y organizo las ideas?</li><li>¿Uso los recursos de la unidad y se entiende quién hace qué?</li><li>¿He comprobado tiempos, concordancia, preposiciones, tildes y puntuación?</li></ol><label class="check-row"><input type="checkbox" id="reviewed" data-reviewed="${id}" ${state.reviewed[id]?'checked':''}> He escrito mi respuesta y la he revisado.</label>`;
 const completed=consolidated(state,id);return `<a class="back-link" href="#route">← Ruta de aprendizaje</a>${eyebrow(`${l.level} · UNIDAD ${index+1} · ${l.minutes} MINUTOS`)}<h1>${e(l.title)}</h1><p class="lead">${e(l.goal)}</p><div class="lesson-status">${badge(l.level)}<span>${completed?'✓ Consolidada según tus registros':'Para consolidar: ≥80% en ejercicios, las cinco valoraciones orales ≥3 y escritura revisada.'}</span></div><nav class="lesson-tabs" aria-label="Actividades de la unidad">${[['learn','Entender'],['quiz','Practicar'],['speak','Hablar'],['write','Escribir']].map(([tab,title])=>`<button data-tab="${tab}" class="${currentTab===tab?'active':''}" aria-pressed="${currentTab===tab}">${title}</button>`).join('')}</nav>${body}<div class="lesson-pagination">${index>0?`<a href="#lesson/${siblings[index-1].id}">← Unidad anterior</a>`:'<span></span>'}${index<siblings.length-1?`<a href="#lesson/${siblings[index+1].id}">Siguiente unidad →</a>`:'<a href="#exams">Comprobar con un modelo DELE →</a>'}</div>`;
}
function conversation(){return `${pageTitle('ESTUDIO ORAL','Una conversación cada vez','Practica sola o con tu pareja. La meta es mantener el hilo, responder y reformular.')}<div class="conversation-panel"><label for="topic">Elige un tema</label><select id="topic">${topics.map(([title],i)=>`<option value="${i}">${e(title)}</option>`).join('')}</select><button class="text-button" id="topic-random">Otro tema ↻</button><div id="topic-content"></div></div><h2>Un encuentro de diez minutos</h2><div class="three-col"><div><span class="step-number">01</span><h3>Entra en confianza</h3><p>Dos minutos sobre el día. Tu compañero escucha y no completa cada frase.</p></div><div><span class="step-number">02</span><h3>Desarrolla y responde</h3><p>Seis minutos con preguntas: ¿por qué?, ¿qué pasó después?, ¿qué cambiarías? Añadid una restricción.</p></div><div><span class="step-number">03</span><h3>Elige dos mejoras</h3><p>Dos minutos de comentarios. Repite una parte con las mejoras y prueba otro tema mañana.</p></div></div><p>Si practicas sola: responde en voz alta, formula una objeción a tu propia idea y contéstala. Esto practica producción; la interacción necesita otra persona.</p>${speakingTools()}${ratingMarkup('conversation')}`;}
function updateTopic(){const topic=topics[Number($('#topic').value)];$('#topic-content').innerHTML=`${badge(state.level)}<h2>${e(topic[0])}</h2><p class="task-prompt">${e(topic[{B1:1,B2:2,C1:3}[state.level]])}</p><div class="topic-followups"><strong>Preguntas para abrir la conversación</strong><p>¿Puedes dar un ejemplo concreto? · ¿Qué fue lo más difícil? · ¿Qué alternativa considerarías? · ¿Qué cambiaría tu opinión?</p></div>`;}
function listening(){return `${pageTitle('BIBLIOTECA DE PRÁCTICA','Escucha. Entiende. Cuéntalo.','Textos originales con preguntas y explicación. La voz sintética es un apoyo; usa los audios humanos oficiales para comprobar tu escucha.')}<div class="library-grid">${library.map(text=>`<a class="library-card" href="#text/${text.id}">${badge(text.level)}<span class="tiny">${text.type}</span><h2>${e(text.title)}</h2><p>${text.text.split(/\s+/).length} palabras · ${text.questions.length} preguntas</p><span>Practicar ↗</span></a>`).join('')}</div><h2>Un ciclo de comprensión</h2><ol class="method-list"><li>Escucha sin transcripción y apunta la idea principal.</li><li>Escucha de nuevo buscando razones, detalles y reservas.</li><li>Responde antes de leer. Después comprueba la evidencia.</li><li>Resume en voz alta y separa tu opinión de la postura de la fuente.</li></ol><p>${link(sources[3].url,'Abrir los audios reales del Instituto Cervantes')}</p>`;}
function textView(id){const text=library.find(t=>t.id===id);if(!text)return pageTitle('NO ENCONTRADO','Texto no encontrado','Elige un texto en la biblioteca.');return `<a class="back-link" href="#listening">← Biblioteca</a>${pageTitle(`${text.level} · ${text.type}`,text.title,'Puedes practicar primero escucha o abrir el texto para trabajar lectura.')}<div class="audio-controls"><label for="voice">Voz en español <select id="voice"><option value="">Cargando voces disponibles…</option></select></label><label for="speed">Velocidad <select id="speed"><option value="0.85">0,85×</option><option value="1" selected>1×</option><option value="1.1">1,1×</option></select></label><button class="button" id="listen-play" data-text="${id}">Escuchar</button><button class="button secondary" id="listen-stop">Detener</button><div id="audio-status" role="status"></div></div><p class="tiny">Voz sintética del navegador. Algunas voces pueden utilizar su servicio de síntesis. No es un audio DELE ni reproduce conversación espontánea.</p><details class="transcript"><summary>Abrir texto o transcripción</summary><p>${e(text.text)}</p></details>${quizMarkup(id,text.questions)}<h2>Ahora úsalo</h2><p>${e(text.task)}</p><label class="editor-label" for="draft">Tu resumen <span id="word-count"></span></label><textarea id="draft" data-draft="${id}" rows="8">${e(state.drafts[id]??'')}</textarea>`;}
function examsPage(){const ex=exams[state.level],saved=state.examResults[state.level]??{};return `${pageTitle('COMPROBAR CON UNA REFERENCIA REAL',`Control DELE ${state.level}`,'Reserva un modelo que no hayas estudiado. Aquí registras resultados y evidencias; la web no certifica tu nivel ni corrige automáticamente producciones orales o escritas.')}<div class="exam-links">${link(ex.model,'Abrir modelo oficial')}${link(sources[3].url,'Audios oficiales')}${link(ex.page,'Estructura oficial')}${ex.guide?link(ex.guide,'Guía de evaluación C1'):''}${link(sources[2].url,'Otros modelos administrados')}</div><p>${e(ex.description)}</p><div class="exam-timing">${['Lectura','Escucha','Escritura','Oral'].map((name,i)=>`<div><strong>${ex.times[i]}<small> min</small></strong><span>${name}</span></div>`).join('')}</div><p class="tiny">La prueba oral tiene además ${ex.prep} minutos de preparación. Sigue las instrucciones, extensiones y tiempos del cuadernillo que elijas.</p><h2>Cómo hacer el control</h2><ol class="method-list"><li>Comprueba que cuadernillo, audio y claves son del mismo modelo. En C1 usa el formato de 2024 para comparar con la estructura actual.</li><li>Haz lectura y escucha sin diccionario ni transcripción, respetando las reproducciones y tiempos indicados.</li><li>Escribe las tareas completas. Realiza la oral con una persona que haga de interlocutora y, si estás de acuerdo, grábala.</li><li>Corrige comprensión con las claves oficiales. Para valorar expresión utiliza la guía y, preferiblemente, una persona formada en evaluación.</li><li>Revisa errores por causa: comprensión, vocabulario, distractor, tiempo, organización o recursos. El siguiente control debe usar otro modelo.</li></ol><form id="exam-form"><h2>Registrar este intento</h2><div class="two-col"><label>Modelo y fecha<input name="model" value="${e(saved.model??'')}" placeholder="Modelo 0 · fecha de realización" maxlength="300" required></label><div class="two-col"><label>Aciertos lectura de ${ex.reading}<input type="number" name="reading" min="0" max="${ex.reading}" step="1" value="${saved.reading??''}" required></label><label>Aciertos escucha de ${ex.listening}<input type="number" name="listening" min="0" max="${ex.listening}" step="1" value="${saved.listening??''}" required></label></div></div><label>Observaciones de escritura y oral<textarea name="notes" rows="6" placeholder="Qué pude hacer, qué me bloqueó y qué evidencia quiero revisar.">${e(saved.notes??'')}</textarea></label><button class="button" type="submit">Guardar control</button><div id="exam-result" role="status"></div></form><h2>Cuándo avanzar</h2><p>Como criterio de estudio, prueba la ruta siguiente si alcanzas al menos 80% en lectura y escucha de un modelo nuevo y puedes completar la producción con claridad. Este 80% es una pauta local deliberadamente exigente, no el aprobado oficial. Si las habilidades difieren, avanza en unas y refuerza otras.</p><p>En el DELE B1, B2 y C1, el aprobado requiere 30 de 50 puntos en cada grupo: lectura + escritura y escucha + oral. No basta sumar 60 sin alcanzar ambos mínimos. Los aciertos de comprensión por sí solos no permiten calcular el resultado global. ${link(sources[4].url,'Ver calificación oficial')}</p>`;}
function examFeedback(){const saved=state.examResults[state.level];if(!saved||!$('#exam-result'))return;const ex=exams[state.level],r=Math.round(saved.reading/ex.reading*100),a=Math.round(saved.listening/ex.listening*100);$('#exam-result').innerHTML=`<strong>Lectura ${r}% · Escucha ${a}%</strong><p>${r>=80&&a>=80?'Superas la pauta local en comprensión. Revisa también escritura y conversación antes de decidir qué reforzar.':'Revisa las preguntas falladas y practica las habilidades con más dificultad. Puedes explorar la ruta siguiente cuando quieras.'} Esto no determina un resultado DELE.</p>`;}
function notebook(){return `${pageTitle('TU CUADERNO','Lo que vas haciendo tuyo','Conserva frases, errores útiles y próximos pasos. Exporta tu trabajo para llevarlo a otro navegador.')}<div class="backup-controls"><button class="button" id="export">Exportar mi progreso</button><label class="button secondary" for="import">Importar una copia</label><input id="import" type="file" accept="application/json,.json" class="file-input"><p class="tiny">Importar sustituye el cuaderno de este navegador; exporta primero si quieres conservarlo. No hay sincronización automática entre dispositivos.</p></div><label class="editor-label" for="notes">Frases y observaciones personales</label><textarea id="notes" rows="10" placeholder="Qué dije · cómo lo diría ahora · una frase propia · cuándo quiero repasarlo">${e(state.notes)}</textarea><h2>Mis borradores</h2>${Object.entries(state.drafts).filter(([,value])=>value.trim()).map(([id,value])=>{const item=lessons.find(l=>l.id===id)??library.find(l=>l.id===id);return item?`<details><summary>${e(item.title)} · ${value.trim().split(/\s+/).length} palabras</summary><p class="preserve">${e(value)}</p><a href="#${id.startsWith('lib-')?'text':'lesson'}/${id}">Volver a la actividad →</a></details>`:'';}).join('')||'<p>Tus textos aparecerán aquí cuando escribas en una unidad o en la biblioteca.</p>'}<h2>Mis puntos de práctica</h2><div class="result-list">${Object.entries(state.results).map(([id,result])=>{const item=lessons.find(l=>l.id===id)??library.find(l=>l.id===id);return item?`<p><strong>${e(item.title)}</strong><span>${result.correct}/${result.total} · ${result.percent}% · ${result.attempts} intento(s)</span></p>`:'';}).join('')||'<p>Todavía no hay ejercicios corregidos.</p>'}</div><p class="notice">Tu cuaderno y las valoraciones se guardan localmente. Borrar los datos del navegador los elimina. La exportación contiene tus textos: guárdala donde quieras conservarlos.</p>`;}
function method(){return `${pageTitle('EMPEZAR SIN ESPERAR AL DIAGNÓSTICO','Una rutina que cabe en tu semana','Empieza en B1 como referencia provisional. Si una unidad te resulta fácil, prueba sus actividades sin leer y pasa a la siguiente.')}<h2>Una sesión de 25 a 35 minutos</h2><ol class="method-list"><li><strong>Recupera durante 5 minutos.</strong> Di tres frases de la sesión anterior sin mirar.</li><li><strong>Entiende durante 8 minutos.</strong> Lee una sección y explica la diferencia entre dos ejemplos.</li><li><strong>Practica durante 7 minutos.</strong> Responde a preguntas y explica por qué descartas las otras opciones.</li><li><strong>Usa durante 10 minutos.</strong> Habla o escribe sobre tu vida utilizando el recurso.</li><li><strong>Revisa durante 3 minutos.</strong> Guarda una corrección, una frase propia y lo que quieres practicar después.</li></ol><h2>Cuatro encuentros semanales</h2><div class="two-col"><div class="feature-card"><h3>Sesión 1 · Una unidad</h3><p>Comprende un contraste y practica. Una unidad puede ocupar varias sesiones: el tiempo de cada ficha es orientativo.</p></div><div class="feature-card"><h3>Sesión 2 · Comprensión</h3><p>Trabaja un texto o audio y resúmelo sin mirar. Añade una entrevista o conversación real de interés personal.</p></div><div class="feature-card"><h3>Sesión 3 · Conversación</h3><p>Dedica diez minutos a hablar con tu pareja. Corrige al final dos cosas y repite un fragmento.</p></div><div class="feature-card"><h3>Sesión 4 · Escritura y repaso</h3><p>Escribe, revisa y recupera frases de varias unidades. Prueba un tema nuevo para comprobar transferencia.</p></div></div><h2>Cómo ajustar dificultad</h2><p>Con apoyo: utiliza las frases y prepara palabras. Sin guion: oculta las ayudas y responde a preguntas nuevas. Un paso más: añade una objeción, un destinatario distinto o una restricción. Si una tarea exige demasiado apoyo, reduce extensión y practica una sola dificultad. Si es sencilla, entra en B2 o C1 desde el selector: no hay bloqueos.</p><h2>Una primera planificación flexible</h2><p>Semanas 1–3: detecta lagunas en la base B1 y construye una rutina. Semanas 4–7: trabaja los recursos B2 que necesites para conversar. Semana 8: realiza un control con un modelo no estudiado. Semanas 9–12: refuerza lo detectado y explora C1 en habilidades que ya te resulten cómodas. Las semanas orientan la organización; no prometen alcanzar un nivel en un plazo fijo.</p><h2>Repetir y avanzar</h2><p>Repasa frases al día siguiente, unos días después y la semana siguiente; ajusta el intervalo según lo que recuerdes. Las unidades se consideran consolidadas cuando registras ≥80% en sus preguntas, ≥3 en las cinco dimensiones orales y escritura revisada. Es una autoevaluación local. Comprueba el salto de nivel con un modelo oficial nuevo y muestras orales y escritas, no con la repetición del mismo cuestionario.</p><h2>Para tu compañero de conversación</h2><p>Haz preguntas abiertas, espera unos segundos y evita completar cada frase. Si ella no comprende, reformula. Durante la conversación prioriza el mensaje; al final comenta dos dificultades relevantes. Pregunta también qué ha notado ella. Cambiad de tema cuando la práctica se convierta en recitar un guion.</p><a class="button" href="#route">Abrir mi ruta</a>`;}
function sourcesPage(){return `${pageTitle('REFERENCIAS Y ALCANCE','Una guía de estudio con fuentes claras','El contenido didáctico es original. La progresión toma como referencias el MCER y el Plan curricular; los controles enlazan materiales oficiales sin reproducir sus cuadernillos.')}<div class="source-list">${sources.map(source=>`<article><h2>${link(source.url,source.title)}</h2><p>${e(source.note)}</p></article>`).join('')}</div><h2>Qué significan los niveles aquí</h2><p>B1 organiza una base para experiencias y situaciones conocidas; B2 amplía argumentación e interacción; C1 profundiza en matices, registro y mediación. Las etiquetas de las unidades son decisiones didácticas orientativas. Los cuestionarios originales no están validados psicométricamente ni han sido administrados como pruebas oficiales. Puedes contrastar tu desempeño con los modelos DELE enlazados; la web no ha certificado ni medido todavía el nivel de ninguna persona.</p><h2>Datos y funcionamiento</h2><p>No hay cuentas ni servidor de datos de estudio. Tu progreso y borradores se guardan en este navegador; las grabaciones permanecen en la sesión hasta descargarlas. La voz sintética depende del navegador y puede usar su servicio de síntesis. Los enlaces oficiales abren sitios externos. GitHub Pages aloja los archivos públicos de la aplicación; tu cuaderno no forma parte del repositorio.</p><h2>Revisión de referencias</h2><p>Enlaces y estructura consultados el 9 de octubre de 2026. Antes de preparar una convocatoria, comprueba siempre las instrucciones oficiales actuales. Esta guía cubre una selección amplia desde B1 hacia C1; no es un inventario exhaustivo de la lengua ni un curso oficial del Instituto Cervantes.</p>`;}
function clearTools(){clearInterval(timer);timer=null;if('speechSynthesis'in window)window.speechSynthesis.cancel();if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(track=>track.stop());stream=null;recorder=null;if(audioUrl){URL.revokeObjectURL(audioUrl);audioUrl=null;}}
function render(focus=false){clearTools();const hash=location.hash.slice(1)||'home',parts=hash.split('/'),page=parts[0];$('#level').value=state.level;$('#help-toggle').setAttribute('aria-pressed',String(state.english));document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||(page==='lesson'&&a.dataset.nav==='route')||(page==='text'&&a.dataset.nav==='listening')));
 const views={home,route,conversation,listening,exams:examsPage,notebook,method,sources:sourcesPage};$('#main').innerHTML=page==='lesson'?lessonView(parts[1]):page==='text'?textView(parts[1]):(views[page]??home)();bind();if(focus){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}if(page==='conversation')updateTopic();if(page==='text')populateVoices();if(page==='exams')examFeedback();updateCount();}
function updateCount(){const draft=$('#draft');if(!draft)return;const count=draft.value.trim()?draft.value.trim().split(/\s+/).length:0;$('#word-count').textContent=`${count} palabras`;
}
function bind(){
 document.querySelectorAll('[data-level]').forEach(button=>button.addEventListener('click',()=>{state.level=button.dataset.level;save();render();}));
 $('#search')?.addEventListener('input',event=>{const query=event.target.value.trim().toLocaleLowerCase('es');const items=query?lessons.filter(l=>[l.title,l.tag,l.goal,...l.sections.map(s=>s.title)].join(' ').toLocaleLowerCase('es').includes(query)):progress(state.level).list;$('#lesson-list').innerHTML=items.length?items.map(lessonCard).join(''):'<p>No hay coincidencias. Prueba con otra palabra.</p>';});
 document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{currentTab=button.dataset.tab;render();}));
 document.querySelectorAll('[data-quiz]').forEach(form=>{form.addEventListener('submit',event=>{event.preventDefault();const id=form.dataset.quiz,items=lessons.find(l=>l.id===id)?.quiz??library.find(t=>t.id===id)?.questions;try{const data=new FormData(form),answers=items.map((_,i)=>data.has('q'+i)?Number(data.get('q'+i)):-1),result=grade(items,answers);state.results[id]={...result,attempts:(state.results[id]?.attempts??0)+1};save();items.forEach((item,i)=>{const feedback=form.querySelector(`[data-feedback="${i}"]`);feedback.hidden=false;feedback.className='feedback '+(answers[i]===item.answer?'correct':'incorrect');feedback.innerHTML=`<strong>${answers[i]===item.answer?'✓ Correcto':'Revisa esta respuesta'}</strong><p>Respuesta: ${e(item.options[item.answer])}. ${e(item.why)}</p>`;});form.querySelector('.quiz-result').innerHTML=`<strong>${result.correct}/${result.total} · ${result.percent}%</strong><p>${result.percent>=80?'Buen resultado en este ejercicio. Ahora utiliza el recurso en una situación nueva.':'Vuelve a los ejemplos y explica las diferencias antes de repetir.'}</p>`;form.querySelector('[type="submit"]').disabled=true;form.querySelectorAll('input').forEach(input=>input.disabled=true);}catch(error){toast(error.message);}});form.addEventListener('reset',()=>{form.querySelectorAll('[data-feedback]').forEach(el=>el.hidden=true);form.querySelectorAll('input,[type="submit"]').forEach(el=>el.disabled=false);form.querySelector('.quiz-result').textContent='';});});
 $('#draft')?.addEventListener('input',event=>{state.drafts[event.target.dataset.draft]=event.target.value;if(state.reviewed[event.target.dataset.draft]){state.reviewed[event.target.dataset.draft]=false;if($('#reviewed'))$('#reviewed').checked=false;}save();updateCount();});
 $('#reviewed')?.addEventListener('change',event=>{const id=event.target.dataset.reviewed;if(event.target.checked&&!(state.drafts[id]??'').trim()){event.target.checked=false;return toast('Escribe una respuesta antes de marcarla como revisada.');}state.reviewed[id]=event.target.checked;save();toast(event.target.checked?'Escritura revisada.':'La revisión queda pendiente.');});
 document.querySelectorAll('[data-ratings]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form);state.ratings[form.dataset.ratings]=rubric.map((_,i)=>Number(data.get('r'+i)));save();toast('Valoración oral guardada.');}));
 $('#notes')?.addEventListener('input',event=>{state.notes=event.target.value;save();});
 $('#export')?.addEventListener('click',()=>download(JSON.stringify(state,null,2),'denali-progreso.json','application/json'));
 $('#import')?.addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2e6)throw new Error('La copia es demasiado grande.');const validated=validateState(JSON.parse(await file.text()),lessons.map(l=>l.id));state=validated;save();render();toast('Copia importada.');}catch(error){toast(error.message||'No se pudo importar la copia.');}});
 $('#topic')?.addEventListener('change',updateTopic);$('#topic-random')?.addEventListener('click',()=>{const select=$('#topic');select.value=String((Number(select.value)+1+Math.floor(Math.random()*(topics.length-1)))%topics.length);updateTopic();});
 $('#timer-start')?.addEventListener('click',startTimer);$('#timer-reset')?.addEventListener('click',()=>{clearInterval(timer);timer=null;$('#timer-start').disabled=false;$('#timer-display').textContent=String($('#timer-minutes').value).padStart(2,'0')+':00';});$('#timer-minutes')?.addEventListener('change',()=>$('#timer-reset').click());
 $('#record-start')?.addEventListener('click',startRecording);$('#record-stop')?.addEventListener('click',()=>{recorder?.stop();stream?.getTracks().forEach(t=>t.stop());$('#record-stop').disabled=true;$('#record-start').disabled=false;});
 $('#listen-play')?.addEventListener('click',playText);$('#listen-stop')?.addEventListener('click',()=>{window.speechSynthesis?.cancel();$('#audio-status').textContent='Reproducción detenida.';});
 $('#exam-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);state.examResults[state.level]={reading:Number(data.get('reading')),listening:Number(data.get('listening')),notes:String(data.get('notes')),model:String(data.get('model'))};save();examFeedback();toast('Control guardado.');});
}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function startTimer(){clearInterval(timer);let remaining=Number($('#timer-minutes').value)*60;$('#timer-start').disabled=true;timer=setInterval(()=>{remaining--;const display=$('#timer-display');if(!display){clearInterval(timer);return;}display.textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(remaining<=0){clearInterval(timer);timer=null;$('#timer-start').disabled=false;toast('Tiempo terminado. Revisa una o dos mejoras.');}},1000);}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Este navegador no permite grabar aquí. Utiliza la grabadora del móvil.');const output=$('#record-output');try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!document.contains(output)){stream.getTracks().forEach(t=>t.stop());return;}const chunks=[];recorder=new MediaRecorder(stream);recorder.addEventListener('dataavailable',event=>{if(event.data.size)chunks.push(event.data);});const activeRecorder=recorder;recorder.addEventListener('stop',()=>{if(!document.contains(output))return;if(audioUrl)URL.revokeObjectURL(audioUrl);const blob=new Blob(chunks,{type:activeRecorder.mimeType});audioUrl=URL.createObjectURL(blob);const ext=activeRecorder.mimeType.includes('mp4')?'m4a':activeRecorder.mimeType.includes('ogg')?'ogg':'webm';output.innerHTML=`<audio controls src="${audioUrl}"></audio><a href="${audioUrl}" download="denali-conversacion.${ext}">Descargar grabación</a>`;});recorder.start();$('#record-start').disabled=true;$('#record-stop').disabled=false;output.textContent='Grabando. Pulsa terminar antes de descargar.';}catch{stream?.getTracks().forEach(t=>t.stop());toast('No se pudo acceder al micrófono. Revisa el permiso o graba con el móvil.');}}
function populateVoices(){const select=$('#voice');if(!select)return;if(!('speechSynthesis'in window)){select.innerHTML='<option>No hay síntesis de voz</option>';$('#listen-play').disabled=true;return;}const voices=window.speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith('es'));select.innerHTML=voices.length?voices.map(v=>`<option value="${e(v.name)}">${e(v.name)} (${e(v.lang)})</option>`).join(''):'<option value="">Voz automática en español</option>';}
function playText(){if(!('speechSynthesis'in window))return toast('No hay síntesis de voz. Lee el texto o pide a tu compañero que lo lea.');const text=library.find(t=>t.id===$('#listen-play').dataset.text);window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text.text);utterance.lang='es-ES';utterance.rate=Number($('#speed').value);const voice=window.speechSynthesis.getVoices().find(v=>v.name===$('#voice').value);if(voice)utterance.voice=voice;utterance.onstart=()=>{if($('#audio-status'))$('#audio-status').textContent='Escuchando…';};utterance.onend=()=>{if($('#audio-status'))$('#audio-status').textContent='Escucha terminada. Resume la idea antes de responder.';};utterance.onerror=()=>{if($('#audio-status'))$('#audio-status').textContent='No se pudo reproducir. Usa el texto o un audio oficial.';};window.speechSynthesis.speak(utterance);}
$('#level').addEventListener('change',event=>{state.level=event.target.value;save();render();});$('#help-toggle').addEventListener('click',()=>{state.english=!state.english;save();render();toast(state.english?'Ayudas en inglés activadas en las lecciones.':'Ayudas en inglés desactivadas.');});window.addEventListener('hashchange',()=>{currentTab='learn';render(true);});window.addEventListener('pagehide',clearTools);if('speechSynthesis'in window)window.speechSynthesis.addEventListener('voiceschanged',populateVoices);render();
